import os,json,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def transform(g):
    h,w=len(g),len(g[0])
    # find V shapes: connected groups of nonzero cells (8-conn), apex = min-r cell
    cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]]
    groups=[];seen=set()
    for s in cells:
        if s in seen: continue
        st=[s];seen.add(s);grp=[]
        while st:
            r,c=st.pop();grp.append((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(r+dr,c+dc)
                    if n not in seen and 0<=n[0]<h and 0<=n[1]<w and g[n[0]][n[1]]:
                        seen.add(n);st.append(n)
        groups.append(grp)
    fill=set()
    for grp in groups:
        apex=min(grp,key=lambda p:p[0]); a=apex[0]+apex[1]; b=apex[1]-apex[0]
        assert all(p[0]+p[1]==a or p[1]-p[0]==b for p in grp), (grp,apex)
        for r in range(h):
            for c in range(w):
                if g[r][c]==0 and r+c>a and c-r<b:
                    fill.add((r,c))
    return [[2 if (r,c) in fill else g[r][c] for c in range(w)] for r in range(h)]

