import json,os
def lines_and_apexes(g):
    h,w=len(g),len(g[0])
    nz=[(r,c) for r in range(h) for c in range(w) if g[r][c]]
    anti={}  # r+c -> cells
    main={}  # c-r -> cells
    for r,c in nz:
        anti.setdefault(r+c,[]).append((r,c))
        main.setdefault(c-r,[]).append((r,c))
    apexes=[]
    for s,ac in anti.items():
        for d,mc in main.items():
            r0=(s-d)//2; c0=(s+d)//2
            if (s-d)%2==0 and 0<=r0<h and 0<=c0<w and g[r0][c0] and len(ac)>1 and len(mc)>1:
                apexes.append((r0,c0,s,d,ac,mc))
    return apexes

def transform(g):
    h,w=len(g),len(g[0])
    fill=set()
    for (r0,c0,s,d,ac,mc) in lines_and_apexes(g):
        a_down = any(r>r0 for r,c in ac)   # anti arm extends downward
        m_down = any(r>r0 for r,c in mc)   # main arm extends downward
        for r in range(h):
            for c in range(w):
                if g[r][c]: continue
                ok1 = (r+c>s) if a_down else (r+c<s)
                ok2 = (c-r<d) if m_down else (c-r>d)
                if ok1 and ok2: fill.add((r,c))
    return [[2 if (r,c) in fill else g[r][c] for c in range(w)] for r in range(h)]

